-- V18: metric definition registry for the 79 v3 entries. Re-entrant: the
-- table uses IF NOT EXISTS and the seed uses ON CONFLICT DO UPDATE, so the
-- whole file can be re-applied without duplicating or losing rows.
CREATE TABLE IF NOT EXISTS platform.metric_definition (
  metric_id        text PRIMARY KEY,
  name_zh          text NOT NULL,
  domain           text NOT NULL CHECK (domain IN ('bank', 'insurance', 'customer')),
  evidence_basis   text NOT NULL CHECK (evidence_basis IN ('regulatory', 'industry', 'none')),
  publishable      boolean NOT NULL,
  inference        boolean NOT NULL DEFAULT false,
  formula_disabled boolean NOT NULL DEFAULT false,
  missing          text,
  evidence_status  text NOT NULL CHECK (evidence_status IN ('EVIDENCED', 'EVIDENCE_MISSING', 'INDUSTRY_ONLY', 'NO_SOURCE')),
  note             text,
  updated_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS metric_definition_basis_idx
  ON platform.metric_definition (evidence_basis, publishable);

ON CONFLICT (metric_id) DO UPDATE SET
  name_zh = EXCLUDED.name_zh,
  domain = EXCLUDED.domain,
  evidence_basis = EXCLUDED.evidence_basis,
  publishable = EXCLUDED.publishable,
  inference = EXCLUDED.inference,
  formula_disabled = EXCLUDED.formula_disabled,
  missing = EXCLUDED.missing,
  evidence_status = EXCLUDED.evidence_status,
  note = EXCLUDED.note,
  updated_at = now();
